#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "Cloudflare preview setup"

# The workflow that will use these values, so the project name cannot drift from it.
WORKFLOW=".github/workflows/preview.yml"
PREVIEW_PROJECT=$(grep -E '^[[:space:]]+PREVIEW_PROJECT:' "$WORKFLOW" 2>/dev/null | head -n1 | awk '{print $2}')
PREVIEW_PROJECT="${PREVIEW_PROJECT:-artisan-preview}"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Your Cloudflare account id"

say "Every Cloudflare API call is scoped to an account, so the token is issued for one"
say "account and the workflow needs its id."
say ""
open_url "https://dash.cloudflare.com"
step "Sign in, or create a free account if you have none (Pages and Access are free)."
step "Look at the address bar: dash.cloudflare.com/<account-id>/... - the 32-character"
step "hex string right after the host IS the account id."
step "No address bar id? Open Workers & Pages > Overview, the right sidebar shows"
step "'Account ID', with a copy button."
ask CLOUDFLARE_ACCOUNT_ID "Paste the account id (32 hex characters):"
if [[ ! "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; then
  warn "That does not look like an account id (expected 32 hex characters)."
  warn "Anything else and every API call below will fail, so stopping here."
  exit 1
fi
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
note "Non-secret, so it is kept in $ENV_FILE for re-runs. The token is not written to disk."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the API token"

say "This token can deploy to Pages and nothing else. It cannot read your domains,"
say "DNS, R2 or account billing."
say ""
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Select 'Create Token'."
step "Select 'Create Custom Token' > 'Get started' (not a template)."
step "Token name: artisan-preview-deploy"
step ""
say "Under 'Permission policies' there is an 'Edit policy' panel with TWO things:"
say "a resource scope at the top, and the permission list underneath it."
step "Resource scope (the dropdown): leave it on 'Entire Account'."
step "  Pages projects are not a scope you can pick, and a project that does not exist"
step "  yet could not be scoped to anyway. The scope is harmless on its own - what the"
step "  token can DO comes from the permission list below, not from this dropdown."
step "Permission list: type 'pages' in its search box, then tick 'Edit' on the row"
step "  'Pages' under 'Developer Platform' - the one described as 'Grants read access"
step "  to Cloudflare Pages'."
warn "  Searching 'pages' also matches 'Account Custom Pages' (Rules & Configuration)"
warn "  and 'Access: Custom Pages' (Cloudflare One). Both are unrelated: the first is"
warn "  the branded error-page feature, the second is custom login pages. Leave them."
step "  Only 'Edit', not 'Read': Read cannot create the project or deploy."
step "Select '+ Add policy' to commit it to the token."
step "Do NOT use 'Bulk Select': it ticks every permission in the account."
step ""
say "Optional, both in the same form:"
step "Token expiration: 3 months, so a leaked token dies on its own."
warn "Also on this form: leave 'Client IP Address Filtering' empty. GitHub's runners change IP on every"
warn "run, so an IP allowlist makes the token fail intermittently and confusingly."
say ""
step "Select 'Continue to summary' > 'Create Token'."
step "Copy the token now - Cloudflare shows it exactly once."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token:"
if [[ -z "$CLOUDFLARE_API_TOKEN" ]]; then
  warn "No token captured; re-run this wizard when you have it."
  exit 1
fi
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
note "Token held in memory only for this run - it goes straight into a GitHub secret."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Prove the token works"

say "Before it goes anywhere near CI, check it can actually do the job. Two calls:"
say "one to prove the token is live, one to prove it can reach Pages."
say ""
resp=$(curl -s --max-time 20 "https://api.cloudflare.com/client/v4/user/tokens/verify" \
  -H "Authorization: Bearer ${CLOUDFLARE_API_TOKEN}" || true)
if grep -qE '"status"[[:space:]]*:[[:space:]]*"active"' <<<"$resp"; then
  say "✓ token is active"
else
  warn "Cloudflare did not confirm the token as active:"
  note "${resp:0:300}"
  warn "Usually a truncated paste or an expired token. Re-run instead of pushing on."
  exit 1
fi

resp=$(curl -s --max-time 20 \
  "https://api.cloudflare.com/client/v4/accounts/${CLOUDFLARE_ACCOUNT_ID}/pages/projects" \
  -H "Authorization: Bearer ${CLOUDFLARE_API_TOKEN}" || true)
if grep -q '"success"[[:space:]]*:[[:space:]]*true' <<<"$resp"; then
  say "✓ token can list Pages projects"
else
  warn "The token cannot reach Pages on this account:"
  note "${resp:0:300}"
  warn "Check the policy is Account > Cloudflare Pages > Edit, scoped to THIS account"
  warn "(account id ${CLOUDFLARE_ACCOUNT_ID})."
  exit 1
fi

if grep -q "\"name\"[[:space:]]*:[[:space:]]*\"${PREVIEW_PROJECT}\"" <<<"$resp"; then
  say "✓ project '${PREVIEW_PROJECT}' already exists"
else
  say "Creating the Pages project '${PREVIEW_PROJECT}'..."
  resp=$(curl -s -X POST \
    "https://api.cloudflare.com/client/v4/accounts/${CLOUDFLARE_ACCOUNT_ID}/pages/projects" \
    -H "Authorization: Bearer ${CLOUDFLARE_API_TOKEN}" -H "Content-Type: application/json" \
    --data "{\"name\":\"${PREVIEW_PROJECT}\",\"production_branch\":\"main\"}" || true)
  if grep -q '"success"[[:space:]]*:[[:space:]]*true' <<<"$resp"; then
    say "✓ created '${PREVIEW_PROJECT}'"
  else
    warn "Could not create the project:"
    note "${resp:0:300}"
    warn "Not fatal - the workflow creates it on the first deploy. Carrying on."
  fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Store the GitHub secrets"

say "These are the two names the workflow reads. Nothing else is needed."
say ""
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Protect the previews"

say "Right now anyone who guesses pr-<number>.${PREVIEW_PROJECT}.pages.dev can read a"
say "preview. The number is sequential, so that is not much of a secret."
say ""
open_url "https://dash.cloudflare.com/${CLOUDFLARE_ACCOUNT_ID}/workers-and-pages"
step "Open the '${PREVIEW_PROJECT}' project > Settings."
step "Find 'Prevent visitors from accessing preview deployments' (it may sit under an"
step "  Access / Deployment access heading) and switch it on."
step "If asked to set up Zero Trust first: pick a team name, choose the free plan, and"
step "  add your email under Access > Users. You only have to do this once."
say ""
note "Skipping this is allowed. The preview still works from your phone; the workflow"
note "will just report, honestly, that the deployment answers without a login."
pause "Press Enter when done (or to skip)"

say ""
say "Optional: build the preview now to see it end to end."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  pr=$(gh pr list --state open --limit 1 --json number --jq '.[0].number' 2>/dev/null || true)
  if [[ -n "${pr}" ]]; then
    if confirm "Run the preview workflow for pull request #${pr}?"; then
      if gh workflow run preview.yml -f pr="${pr}" >/dev/null 2>&1; then
        say "✓ queued - watch it at:"
        note "$(gh repo view --json nameWithOwner --jq '.nameWithOwner' 2>/dev/null | sed 's|^|https://github.com/|')/actions/workflows/preview.yml"
        note "Phone URL when it finishes: https://pr-${pr}.${PREVIEW_PROJECT}.pages.dev"
      else
        warn "Could not start the workflow - run it from the Actions tab instead."
      fi
    fi
  else
    note "No open pull request to build; skip this."
  fi
else
  note "gh is not available here, so start the workflow from the Actions tab."
fi

finish
}

run_wizard "$@"; exit
